    checkTaskForCases: function() { //To update "fund task status" on case based on tasks associated with that case
        var flag = false;
        var taskGR = new GlideRecord('x_hsb11_mss_fund_0_funds_task');
        taskGR.addEncodedQuery('stateNOT IN203,201^fund_case=' + current.fund_case);
        taskGR.query();
        if (taskGR.next())
            flag = true;
        var caseGR = new GlideRecord('x_hsb11_mss_fund_0_funds_case');
        if (caseGR.get(current.fund_case)) {
            if (flag == true)
                caseGR.funds_tasks_status = 'Open Tasks';
            else
                caseGR.funds_tasks_status = 'All Closed';
            caseGR.update();
        }
    },

    checkActiveTasks: function() { // MSS_Funds_Client_UtilsFUNDS-54: Return true if any open task present for case
        var caseID = this.getParameter('sysparm_caseID');
        var grTask = new GlideRecord('x_hsb11_mss_fund_0_funds_task');
        grTask.addEncodedQuery('stateNOT IN203,201^fund_case=' + caseID); //State is not in Closed - Evaluated By FA/ Transaction Captured
        grTask.query();
        if (grTask.next())
            return true;

    },

    checkTaskAssignedTo: function() {
        //MSSFUNDS-54: Check if user is assigned to any of the task from list
        var userId = this.getParameter('sysparm_userId');
        var caseId = this.getParameter('sysparm_caseId');
        var grTask = new GlideRecord('x_hsb11_mss_fund_0_funds_task');
        grTask.addEncodedQuery('fund_case=' + caseId + '^assigned_to=' + userId);
        grTask.query();
        if (grTask.next())
            return true;


    },

});
